// Spring Boot's auto-configuration (runs AFTER user config)
@Configuration
public class DataSourceAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean(DataSource.class)  // Only if no DataSource exists
    public DataSource dataSource(DataSourceProperties props) {
        return DataSourceBuilder.create()
            .url(props.getUrl())
            .build();
    }
}

// Your custom configuration (runs BEFORE auto-config)
@Configuration
public class CustomDataSourceConfig {

    @Bean
    public DataSource dataSource() {  // No conditions needed
        var config = new HikariConfig();
        config.setJdbcUrl("jdbc:postgresql://localhost/mydb");
        config.setMaximumPoolSize(20);  // Custom pool size
        config.setConnectionTimeout(5000);  // Custom timeout
        return new HikariDataSource(config);
    }
}
// Result: Your HikariDataSource bean exists first.
// When auto-config checks @ConditionalOnMissingBean, it finds yours and skips its default.
