@Configuration
public class SchedulerConfig {

    @Bean
    @ConditionalOnProperty(name = "app.scheduler.enabled", havingValue = "true")
    public TaskScheduler productionScheduler() {
        var scheduler = new ThreadPoolTaskScheduler();
        scheduler.setPoolSize(10);
        scheduler.setThreadNamePrefix("prod-scheduler-");
        scheduler.initialize();
        return scheduler;
    }

    @Bean
    @ConditionalOnProperty(name = "app.payment.mock", havingValue = "true", matchIfMissing = false)
    public PaymentGateway mockPaymentGateway() {
        return new MockPaymentGateway(); // returns successful responses always
    }

    @Bean
    @ConditionalOnProperty(name = "app.payment.mock", havingValue = "false")
    public PaymentGateway realPaymentGateway() {
        return new StripePaymentGateway(); // calls external Stripe API
    }
}
