// Boot auto-configures JPA from the classpath (same in every environment).
// Profiles then choose the environment-specific DataSource.
@Configuration
public class DataSourceConfig {

    @Bean
    @Profile("dev")
    public DataSource devDataSource() {                 // in-memory H2 for local dev
        return DataSourceBuilder.create()
            .url("jdbc:h2:mem:devdb")
            .build();
    }

    @Bean
    @Profile("prod")
    public DataSource prodDataSource(DataSourceProperties props) { // real Postgres in prod
        return DataSourceBuilder.create()
            .url(props.getUrl())
            .username(props.getUsername())
            .password(props.getPassword())
            .build();
    }
}
// Activate with spring.profiles.active=dev (or prod).
